  ('clofazimina', 'Clofazimina', 'Clofazimine', 'Antituberculoso de segunda linha (riminofenilazina)', 'Second-line anti-TB (riminofenylazine)', ARRAY['Lamprene'], 'published', 132),
  ('amicacina', 'Amicacina', 'Amikacin', 'Antituberculoso de segunda linha (aminoglicosídeo)', 'Second-line anti-TB (aminoglycoside)', ARRAY['Amikin'], 'published', 133),
  ('etionamida', 'Etionamida', 'Ethionamide', 'Antituberculoso de segunda linha (tioidazona)', 'Second-line anti-TB (thioamide)', ARRAY['Trecator'], 'published', 134),
  ('protionamida', 'Protionamida', 'Prothionamide', 'Antituberculoso de segunda linha (tioidazona)', 'Second-line anti-TB (thioamide)', ARRAY['Protothionamide'], 'published', 135),
  ('terizidona', 'Terizidona', 'Terizidone', 'Antituberculoso de segunda linha (oxazolidinona)', 'Second-line anti-TB (oxazolidinone)', ARRAY['Terizidone'], 'published', 136),
